<div x-data="brandAssistant({ endpoint: @js(route('brand.assistant.ask')), page: @js(request()->path()) })" class="fixed bottom-5 right-5 z-50">
 <section x-cloak x-show="open" x-transition class="mb-3 flex h-[min(620px,75vh)] w-[min(390px,calc(100vw-2rem))] flex-col overflow-hidden rounded-3xl border border-emerald-200 bg-white shadow-2xl" aria-label="Assistant TexTileGuide">
  <header class="flex items-center justify-between bg-gradient-to-r from-emerald-950 to-teal-800 p-4 text-white"><div class="flex items-center gap-3"><span class="grid h-10 w-10 place-items-center rounded-2xl bg-white/15 text-lg">✦</span><div><h2 class="font-black">{{ config('brand_assistant.name') }}</h2><p class="text-[11px] text-emerald-200">Guide IA de votre espace marque</p></div></div><button @click="open=false" class="rounded-lg p-2 hover:bg-white/10" aria-label="Fermer">✕</button></header>
  <div x-ref="messages" class="flex-1 space-y-3 overflow-y-auto bg-emerald-50/40 p-4"><template x-for="(message,index) in messages" :key="index"><div :class="message.role==='user'?'ml-8 bg-emerald-700 text-white':'mr-8 border bg-white text-slate-700'" class="rounded-2xl p-3 text-sm leading-6"><p class="whitespace-pre-line" x-text="message.content"></p><template x-if="message.links?.length"><div class="mt-3 flex flex-wrap gap-2"><template x-for="link in message.links" :key="link.url"><a :href="link.url" class="rounded-lg bg-emerald-100 px-2.5 py-1.5 text-xs font-black text-emerald-900" x-text="link.label"></a></template></div></template></div></template><div x-show="loading" class="mr-16 rounded-2xl border bg-white p-3 text-sm text-slate-500">TexTileGuide réfléchit…</div></div>
  <div class="border-t bg-white p-3"><div class="mb-2 flex gap-2 overflow-x-auto"><button @click="askSuggestion('Comment créer et faire publier un produit ?')" class="shrink-0 rounded-full bg-slate-100 px-3 py-1.5 text-[11px] font-bold">Créer un produit</button><button @click="askSuggestion('Comment choisir un label ?')" class="shrink-0 rounded-full bg-slate-100 px-3 py-1.5 text-[11px] font-bold">Choisir un label</button><button @click="askSuggestion('Quelle est ma prochaine étape ?')" class="shrink-0 rounded-full bg-slate-100 px-3 py-1.5 text-[11px] font-bold">Prochaine étape</button></div><form @submit.prevent="send" class="flex gap-2"><textarea x-model="question" @keydown.enter.prevent="if(!$event.shiftKey) send()" rows="2" maxlength="1000" placeholder="Comment puis-je…" class="min-h-12 flex-1 resize-none rounded-xl border-slate-300 text-sm"></textarea><button :disabled="loading || question.trim().length<2" class="rounded-xl bg-emerald-700 px-4 font-black text-white disabled:opacity-40">➤</button></form><p x-show="error" x-text="error" class="mt-2 text-xs text-rose-700"></p></div>
 </section>
 <button @click="open=!open" class="ml-auto flex items-center gap-3 rounded-2xl bg-emerald-800 px-4 py-3 font-black text-white shadow-xl transition hover:-translate-y-0.5 hover:bg-emerald-900"><span class="text-xl">✦</span><span x-show="!open">Besoin d’aide ?</span></button>
</div>
